def cta(process=False, capabilities=False):
    stages=''
    if process:
        stages=heading('Our process','Planned with care.<br>Delivered with discipline.')+'<div class="process-grid">'+''.join(f'<div class="stage"><span class="number">0{i+1}</span><div><h3>{title}</h3><p>{copy}</p></div></div>' for i,(title,copy) in enumerate([('Discuss the scope','Tell us about your requirements, location and site conditions.'),('Plan the work','Agree the method, equipment and contingencies before mobilisation.'),('Coordinate delivery','Bring together the people and specialist support for the agreed work.')]))+'</div>'
    if capabilities:
        stages='<div class="section-heading capabilities-intro"><h2>Explore the capabilities<br>behind the work.</h2>'+button('View Services','/services/','outline')+'</div>'+stages
    return f'''<section class="ocean-section"><div class="container">{stages}<div class="contact-glass reveal">{eyebrow('Let’s talk')}<h2>Let’s discuss your next project.</h2><p>Speak with Zhafran Kamarullah, Project Director.</p><div class="cta-actions">{button('WhatsApp Enquiry',wa(),'primary','whatsapp',True)}<div class="contact-inline"><a href="tel:+60122929224">{icon('phone')}{PHONE}</a><a href="mailto:{EMAIL}">{icon('mail')}{EMAIL}</a></div></div></div></div></section>'''
