def service_cards(full=False):
    return '<div class="service-grid'+(' expanded' if full else '')+'">'+''.join(f'<article class="service-card reveal"><div class="service-card-top">{icon(s["icon"])}<span class="service-number">0{i+1}</span></div><h3><a href="/services/{s["slug"]}/">{h(s["title"])}</a></h3><p>{h(s["summary"])}</p>'+('<ul>'+''.join(f'<li>{h(x)}</li>' for x in s['items'])+'</ul>' if full else '')+f'<a class="text-link" href="/services/{s["slug"]}/">Explore service {icon("arrow")}</a></article>' for i,s in enumerate(SERVICES))+'</div>'
def gallery(items,lightbox=False,showcase=False):
    cards=[]
    for name,title,cat,alt,caption in items:
        media=name+'-showcase' if showcase and name in ('salvage','electronics','helmet') else name
        link=f' data-lightbox data-title="{h(title)}" data-caption="{h(caption)}"' if lightbox else ''
        cards.append(f'<article class="photo-card reveal" data-category="{cat}"><a class="photo-link" href="/assets/{media}-1600.webp"{link}>{img(media,alt)}<span class="photo-open">{icon("arrow")}<span class="sr-only">Open {h(title)} photograph</span></span></a><div class="photo-caption"><p class="category">{h(dict(diving="Diving & salvage",equipment="Equipment",training="Training & coordination",uxo="UXO & EOD")[cat])}</p><h3>{h(title)}</h3>'+ (f'<p>{h(caption)}</p>' if lightbox else '')+'</div></article>')
    return '<div class="gallery-grid">'+''.join(cards)+'</div>'
def grouped_gallery():
    data=json.loads((ROOT/'portfolio-groups.json').read_text(encoding='utf-8'))
    by_name={row[0]:row for row in GALLERY}
    return ''.join(f'<section class="portfolio-group" aria-labelledby="group-{g["id"]}"><div class="group-heading"><h2 id="group-{g["id"]}">{h(g["title_en"])}</h2><p>{h(g["description_en"])}</p></div>'+gallery([by_name[a] for a in g['assets']],True)+'</section>' for g in data['groups'])
def faq(items):
    return '<div class="faq-list">'+''.join(f'<details><summary>{h(q)}<span aria-hidden="true">+</span></summary><div><p>{h(a)}</p></div></details>' for q,a in items)+'</div>'
