def schema(path,title,service=None):
    base={'@type':'LocalBusiness','@id':ORIGIN+'/#business','name':'Cyclonite Tech','url':ORIGIN+'/','logo':ORIGIN+'/assets/logo.png','image':ORIGIN+'/assets/salvage-1600.webp','description':'Specialist underwater contractor based in Seri Manjung, Perak, Malaysia.','telephone':'+60122929224','email':EMAIL,'address':{'@type':'PostalAddress','streetAddress':'52A, 1st Floor, Jalan PPMP 3/1, Pusat Perniagaan Manjung Point 3','addressLocality':'Seri Manjung','addressRegion':'Perak','postalCode':'32040','addressCountry':'MY'},'identifier':'SSM 202603272263'}
    graph=[base,{'@type':'WebSite','@id':ORIGIN+'/#website','url':ORIGIN+'/','name':'Cyclonite Tech','publisher':{'@id':ORIGIN+'/#business'}},{'@type':'WebPage','@id':ORIGIN+path+'#webpage','url':ORIGIN+path,'name':title,'isPartOf':{'@id':ORIGIN+'/#website'},'about':{'@id':ORIGIN+'/#business'},'inLanguage':'en-MY'}]
    if path!='/':
        crumbs=[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'}]
        if service: crumbs.append({'@type':'ListItem','position':2,'name':'Services','item':ORIGIN+'/services/'})
        crumbs.append({'@type':'ListItem','position':len(crumbs)+1,'name':service['title'] if service else title.split('|')[0].strip(),'item':ORIGIN+path})
        graph.append({'@type':'BreadcrumbList','itemListElement':crumbs})
    if service: graph.append({'@type':'Service','@id':ORIGIN+path+'#service','name':service['title'],'serviceType':service['title'],'description':service['intro'],'provider':{'@id':ORIGIN+'/#business'},'url':ORIGIN+path})
    return json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('</',r'<\/')
def page(path,title,description,body,active='',service=None,index=True):
    verify=f'<meta name="google-site-verification" content="{h(CFG["google_site_verification"])}">' if CFG.get('google_site_verification') else ''
    html=f'''<!doctype html><html lang="en-MY"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{h(title)}</title><meta name="description" content="{h(description)}"><meta name="robots" content="{'index,follow,max-image-preview:large' if index else 'noindex,follow'}"><link rel="canonical" href="{ORIGIN}{path}">{verify}<meta name="theme-color" content="#081827"><meta property="og:type" content="website"><meta property="og:site_name" content="Cyclonite Tech"><meta property="og:locale" content="en_MY"><meta property="og:title" content="{h(title)}"><meta property="og:description" content="{h(description)}"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:image" content="{ORIGIN}/assets/salvage-1600.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/png" href="/assets/logo.png"><link rel="preload" href="/assets/inter-800.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/site.css?v=3"><link rel="stylesheet" href="/assets/refinements.css?v=4"><script defer src="/assets/site.js?v=3"></script><script type="application/ld+json">{schema(path,title,service)}</script></head><body>{header(active)}<main id="main">{body}</main>{footer()}<dialog id="photo-dialog" aria-labelledby="photo-title"><button class="dialog-close" aria-label="Close photograph">×</button><img id="photo-image" alt=""><div class="dialog-caption"><h2 id="photo-title"></h2><p id="photo-caption"></p><div class="dialog-controls"><button id="photo-prev" aria-label="Previous photograph">← Previous</button><button id="photo-next" aria-label="Next photograph">Next →</button></div></div></dialog></body></html>'''
    dest=OUT/(path.strip('/')+'/index.html' if path!='/' else 'index.html')
    if path=='/404.html': dest=OUT/'404.html'
    dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html,encoding='utf-8')
    if index: PAGES.append(path)

